css:
.loader { --accent: var(--loader-color); width: calc(var(--loader-size) * .6); height: var(--loader-size); display: flex; flex-direction: column; align-items: center; justify-content: center; }
.loader span { width: 100%; height: calc(var(--loader-size) * .08); border: calc(var(--loader-size) * .028) solid var(--accent); border-radius: 50%; margin: calc(var(--loader-size) * .012) 0; animation: coil calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .1); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes coil { 0%, 100% { transform: scaleX(.5); opacity: .4; } 50% { transform: scaleX(1); opacity: 1; } }
